def test_non_sqlite_maintenance_uses_bounded_worker_pool(store: SqlAlchemyStore, monkeypatch):
    if store.engine.dialect.name == "sqlite":
        pytest.skip("requires a backend that supports concurrent writers")

    exp_a = store.create_experiment(f"exp-{uuid.uuid4()}")
    exp_b = store.create_experiment(f"exp-{uuid.uuid4()}")
    _new_trace(store, exp_a, DAY_A_MS)
    _new_trace(store, exp_b, DAY_B_MS)
    barrier = Barrier(2)
    worker_threads = set()

    def rebuild(*_args, **_kwargs):
        worker_threads.add(get_ident())
        barrier.wait(timeout=10)
        return "built"

    monkeypatch.setattr(trace_rollups, "_rebuild_partition", rebuild)

    stats = run_sql_trace_rollups(
        store.engine,
        now_ms=FUTURE_NOW_MS,
        max_partitions_per_run=2,
        max_workers=2,
    )

    assert stats.trace_metric.built == 2
    assert len(worker_threads) == 2


@pytest.mark.parametrize("timestamp", [-(2**63), -1, 0, 1, 2**63 - 1,
                                       -86_400_000_000_001, -86_400_000_000_000,
                                       86_399_999_999_999, 86_400_000_000_000])
@pytest.mark.parametrize("interval", [1, 60, 86400])
def test_postgres_span_bucket_integer_arithmetic(store, timestamp, interval):
    expression = get_time_bucket_expression(MetricViewType.SPANS, interval, "postgresql")
    expression = visitors.replacement_traverse(
        expression, {},
        lambda node: literal(timestamp) if node.compare(SqlSpan.start_time_unix_nano) else None,
    )
    # SQLite and PostgreSQL both truncate integer division toward zero and retain the
    # dividend's sign for remainders, so this also exercises BIGINT boundary arithmetic.
    with store.ManagedSessionMaker() as session:
        value = session.execute(select(expression)).scalar_one()
    assert value == (timestamp // (interval * 1_000_000_000)) * interval * 1000


